<div class="d-flex justify-content-between"><div><h1>PSU-CAT Proctoring</h1><p>Security incidents appear here as they arrive.</p></div><a class="btn btn-outline-primary" href="{{ route('admin.admission.index') }}">Admission setup</a></div>
<div class="card page-card"><div class="card-body"><table class="table table-sm" id="incidents"><thead><tr><th>Time</th><th>Applicant</th><th>Incident</th><th>Strike</th></tr></thead><tbody></tbody></table></div></div><div class="toast-container position-fixed top-0 end-0 p-3" id="alerts"></div>
<script>let cursor=0;const url=@json(route('admin.admission.incidents'));async function refresh(){try{const response=await fetch(url+'?after='+cursor,{headers:{Accept:'application/json'}});if(!response.ok)return;const incidents=await response.json();for(const item of incidents){cursor=Math.max(cursor,item.log_id);const row=document.createElement('tr');for(const value of [item.created_at,item.last_name+', '+item.first_name,item.incident_type,item.strike_number]){const cell=document.createElement('td');cell.textContent=value;row.appendChild(cell)}document.querySelector('#incidents tbody').prepend(row);const alert=document.createElement('div');alert.className='toast show p-3 bg-warning';alert.textContent=item.last_name+', '+item.first_name+' · '+item.incident_type+' · Strike '+item.strike_number;document.getElementById('alerts').appendChild(alert);setTimeout(()=>alert.remove(),5000)}}catch{}}refresh();setInterval(refresh,4000);</script>
@endsection
